from itertools import combinations

def max_size_no_condition(n):
    S = list(range(1, n + 1))
    max_size = 0

    def has_condition(A):
        for x, y, z in combinations(A, 3):
            if (x + y + z) % 2 == 0:
                arr = sorted([x, y, z])
                if arr[0] + arr[1] > arr[2]:
                    return True
        return False

    # This is still an exponential search.
    # We can use a backtracking/brute force approach.
    # But for small n, let's just try to find the max size.

    import itertools
    for r in range(n, 0, -1):
        for A in itertools.combinations(S, r):
            if not has_condition(A):
                return r
    return 0

for n in range(1, 15):
    print(f"n={n}, max_size={max_size_no_condition(n)}")

